// E2E tests need longer timeouts
vi.setConfig({ testTimeout: 600000, hookTimeout: 60000 })

const __filename = fileURLToPath(import.meta.url)
const __dirname = dirname(__filename)
const REPO_ROOT = join(__dirname, '../..')
const MCP_SERVER_PATH = join(REPO_ROOT, 'dist/index.js')

interface MCPRequest {
  jsonrpc: "2.0"
  id: number
  method: string
  params?: unknown
}

interface MCPResponse {
  jsonrpc: "2.0"
  id: number
  result?: unknown
  error?: { code: number; message: string }
}

async function sendMCPRequest(serverProcess: any, request: MCPRequest): Promise<MCPResponse> {
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      reject(new Error("MCP request timeout"))
    }, 5000)

    let buffer = ""
    const onData = (chunk: Buffer) => {
      buffer += chunk.toString()
      const lines = buffer.split("\n")

      for (let i = 0; i < lines.length - 1; i++) {
        const line = lines[i].trim()
        if (line) {
          try {
            const response = JSON.parse(line)
            if (response.id === request.id) {
              clearTimeout(timeout)
              serverProcess.stdout.off("data", onData)
              resolve(response)
            }
          } catch (e) {
            // Ignore parse errors for non-JSON lines
          }
        }
      }
      buffer = lines[lines.length - 1]
    }

    serverProcess.stdout.on("data", onData)
    serverProcess.stdin.write(JSON.stringify(request) + "\n")
  })
}

async function initialize(serverProcess: any): Promise<void> {
  await sendMCPRequest(serverProcess, {
    jsonrpc: "2.0",
    id: 1,
    method: "initialize",
    params: {
      protocolVersion: "2024-11-05",
      capabilities: {},
      clientInfo: { name: "test-client", version: "1.0.0" },
    },
  })
}

describe("MCP Server Registration", () => {
  beforeAll(() => {
    console.log("Building MCP server...")
    execSync("pnpm build", { cwd: REPO_ROOT, stdio: "inherit" })
  })

  it("should register exactly the thin-wrapper tools", async () => {
    const serverProcess = spawn("node", [MCP_SERVER_PATH], {
      stdio: ["pipe", "pipe", "inherit"],
    })

    try {
      await initialize(serverProcess)

      const toolsResponse = await sendMCPRequest(serverProcess, {
        jsonrpc: "2.0",
        id: 2,
        method: "tools/list",
      })

      expect(toolsResponse.result).toBeDefined()
      const tools = (toolsResponse.result as any).tools
      const toolNames = tools.map((t: any) => t.name).sort()

      // Thin wrapper: server discovery/proxy, browser automation, and a
      // version-aware docs gateway. The upgrade/cache-components knowledge tools,
      // prompts, and resources were removed (workflows are skills); nextjs_docs
      // no longer fetches — it points at the bundled docs in node_modules.
      expect(toolNames).toEqual([
        "browser_eval",
        "nextjs_call",
        "nextjs_docs",
        "nextjs_index",
      ])
    } finally {
      serverProcess.kill()
    }
  }, 10000)

  it("should not advertise any prompts", async () => {
    const serverProcess = spawn("node", [MCP_SERVER_PATH], {
      stdio: ["pipe", "pipe", "inherit"],
    })

    try {
      await initialize(serverProcess)

      const promptsResponse = await sendMCPRequest(serverProcess, {
        jsonrpc: "2.0",
        id: 2,
        method: "prompts/list",
      })

      // The server no longer declares the prompts capability, so this is an error.
      expect(promptsResponse.error).toBeDefined()
    } finally {
      serverProcess.kill()
    }
  }, 10000)

  it("should not advertise any resources", async () => {
    const serverProcess = spawn("node", [MCP_SERVER_PATH], {
      stdio: ["pipe", "pipe", "inherit"],
    })

    try {
      await initialize(serverProcess)

      const resourcesResponse = await sendMCPRequest(serverProcess, {
        jsonrpc: "2.0",
        id: 2,
        method: "resources/list",
      })

      // The server no longer declares the resources capability, so this is an error.
      expect(resourcesResponse.error).toBeDefined()
    } finally {
      serverProcess.kill()
    }
  }, 10000)

  it("should successfully call a tool", async () => {
    const serverProcess = spawn("node", [MCP_SERVER_PATH], {
      stdio: ["pipe", "pipe", "inherit"],
    })

    try {
      await initialize(serverProcess)

      // nextjs_index discovers running dev servers; it succeeds even when none
      // are running (returning a "no servers found" message), so it is safe to
      // call without test infrastructure.
      const toolResponse = await sendMCPRequest(serverProcess, {
        jsonrpc: "2.0",
        id: 2,
        method: "tools/call",
        params: {
          name: "nextjs_index",
          arguments: {},
        },
      })

      expect(toolResponse.result).toBeDefined()
      const content = (toolResponse.result as any).content
      expect(content).toBeDefined()
      expect(content.length).toBeGreaterThan(0)
    } finally {
      serverProcess.kill()
    }
  }, 10000)
})

import { describe, it, expect, beforeEach } from "vitest"
import { mcpTelemetryTracker, resetMcpTelemetry, getMcpTelemetryUsage } from "../../src/telemetry/mcp-telemetry-tracker.js"

describe("MCP Telemetry Tracker", () => {
  beforeEach(() => {
    // Reset tracker state before each test
    resetMcpTelemetry()
  })

  it("should start with empty state", () => {
    expect(mcpTelemetryTracker.hasUsage()).toBe(false)
    expect(getMcpTelemetryUsage()).toEqual([])
  })

  it("should track a single tool invocation", () => {
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_index")

    expect(mcpTelemetryTracker.hasUsage()).toBe(true)
    const usages = getMcpTelemetryUsage()
    expect(usages).toHaveLength(1)
    expect(usages[0]).toEqual({
      featureName: "mcp/nextjs_index",
      invocationCount: 1,
    })
  })

  it("should increment count on repeated calls", () => {
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_call")
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_call")
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_call")

    const usages = getMcpTelemetryUsage()
    expect(usages).toHaveLength(1)
    expect(usages[0]).toEqual({
      featureName: "mcp/nextjs_call",
      invocationCount: 3,
    })
  })

  it("should track multiple different tools", () => {
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_index")
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_call")
    mcpTelemetryTracker.recordToolCall("mcp/browser_eval")
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_call")

    const usages = getMcpTelemetryUsage()
    expect(usages).toHaveLength(3)

    // Convert to map for easier testing
    const usageMap = new Map(usages.map((u) => [u.featureName, u.invocationCount]))

    expect(usageMap.get("mcp/nextjs_index")).toBe(1)
    expect(usageMap.get("mcp/nextjs_call")).toBe(2)
    expect(usageMap.get("mcp/browser_eval")).toBe(1)
  })

  it("should track all MCP tools", () => {
    mcpTelemetryTracker.recordToolCall("mcp/browser_eval")
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_index")
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_call")

    const usages = getMcpTelemetryUsage()
    expect(usages).toHaveLength(3)

    const toolNames = usages.map((u) => u.featureName)
    expect(toolNames).toContain("mcp/browser_eval")
    expect(toolNames).toContain("mcp/nextjs_index")
    expect(toolNames).toContain("mcp/nextjs_call")
  })

  it("should reset tracking state", () => {
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_index")
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_call")

    expect(mcpTelemetryTracker.hasUsage()).toBe(true)

    resetMcpTelemetry()

    expect(mcpTelemetryTracker.hasUsage()).toBe(false)
    expect(getMcpTelemetryUsage()).toEqual([])
  })

  it("should handle realistic usage patterns", () => {
    // Simulate a typical session
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_index") // Discover servers
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_call") // Call runtime tool
    mcpTelemetryTracker.recordToolCall("mcp/nextjs_call") // Call another tool
    mcpTelemetryTracker.recordToolCall("mcp/browser_eval") // Browser testing
    mcpTelemetryTracker.recordToolCall("mcp/browser_eval")

    const usages = getMcpTelemetryUsage()
    const usageMap = new Map(usages.map((u) => [u.featureName, u.invocationCount]))

    expect(usageMap.get("mcp/nextjs_index")).toBe(1)
    expect(usageMap.get("mcp/nextjs_call")).toBe(2)
    expect(usageMap.get("mcp/browser_eval")).toBe(2)
  })
})

